#include "test_harness.hpp"
#include "../core/native_forage_recipe.hpp"
#include <limits>
using namespace voxel::world_backend;
static NativeForageRecipe recipe(NativeForageGrammar g){ if(g==NativeForageGrammar::aloe)return{"aloe","aloePatch","aloe",1,3,.5F,g,NativeForageNavigationPolicy::nonblocking};if(g==NativeForageGrammar::mushroom)return{"mush","mushroomCluster","mirecap",1,3,.5F,g,NativeForageNavigationPolicy::nonblocking};if(g==NativeForageGrammar::frost_herb)return{"frost","frostHerbPatch","frostHerb",1,2,.5F,g,NativeForageNavigationPolicy::nonblocking};return{"berry","berryBush","berries",2,4,.56F,g,NativeForageNavigationPolicy::blocking}; }
VWB_TEST(native_forage_recipe_catalog_admits_only_live_typed_recipe_pairs){for(auto g:{NativeForageGrammar::berry,NativeForageGrammar::aloe,NativeForageGrammar::mushroom,NativeForageGrammar::frost_herb})VWB_EXPECT_EQ(g,NativeForageRecipeCatalog::admit(recipe(g)).grammar);}
VWB_TEST(native_forage_recipe_catalog_rejects_ambiguous_fallbacks_and_invalid_physics){auto r=recipe(NativeForageGrammar::berry);r.material_id="other";VWB_EXPECT_THROW(NativeForageRecipeRejected,NativeForageRecipeCatalog::admit(r));r=recipe(NativeForageGrammar::berry);r.recipe_id="";VWB_EXPECT_THROW(NativeForageRecipeRejected,NativeForageRecipeCatalog::admit(r));r=recipe(NativeForageGrammar::berry);r.drop_min=0;VWB_EXPECT_THROW(NativeForageRecipeRejected,NativeForageRecipeCatalog::admit(r));r=recipe(NativeForageGrammar::berry);r.drop_max=1;VWB_EXPECT_THROW(NativeForageRecipeRejected,NativeForageRecipeCatalog::admit(r));r=recipe(NativeForageGrammar::berry);r.collider_radius=std::numeric_limits<float>::infinity();VWB_EXPECT_THROW(NativeForageRecipeRejected,NativeForageRecipeCatalog::admit(r));}
VWB_TEST(native_forage_recipe_catalog_rejects_each_wrong_profile_mapping){for(auto g:{NativeForageGrammar::berry,NativeForageGrammar::aloe,NativeForageGrammar::mushroom,NativeForageGrammar::frost_herb}){auto r=recipe(g);r.drop_id="wrong";VWB_EXPECT_THROW(NativeForageRecipeRejected,NativeForageRecipeCatalog::admit(r));}auto r=recipe(NativeForageGrammar::berry);r.navigation=NativeForageNavigationPolicy::nonblocking;VWB_EXPECT_THROW(NativeForageRecipeRejected,NativeForageRecipeCatalog::admit(r));r=recipe(NativeForageGrammar::berry);r.grammar=static_cast<NativeForageGrammar>(99);VWB_EXPECT_THROW(NativeForageRecipeRejected,NativeForageRecipeCatalog::admit(r));r=recipe(NativeForageGrammar::berry);r.collider_radius=0;VWB_EXPECT_THROW(NativeForageRecipeRejected,NativeForageRecipeCatalog::admit(r));}
